solutionCode:
def describe_http_status(status_code: int) -> dict:
    known = {
        200: ('success', 'OK'),
        201: ('success', 'Created'),
        400: ('client_error', 'Bad Request'),
        401: ('client_error', 'Unauthorized'),
        403: ('client_error', 'Forbidden'),
        404: ('client_error', 'Not Found'),
        500: ('server_error', 'Internal Server Error')
    }
    if status_code in known:
        cat, txt = known[status_code]
    elif 200 <= status_code < 300:
        cat, txt = 'success', 'Success'
    elif 400 <= status_code < 500:
        cat, txt = 'client_error', 'Client Error'
    else:
        cat, txt = 'server_error', 'Server Error'
    return {'code': status_code, 'category': cat, 'text': txt}

import json

def process_rest_payload(raw_json: str, required_fields: list[str]) -> tuple[bool, dict | str]:
    try:
        data = json.loads(raw_json)
    except Exception:
        return False, 'Invalid JSON'
    if not isinstance(data, dict):
        return False, 'Payload must be a JSON object'
    for field in required_fields:
        if field not in data:
            return False, f'Missing required field: {field}'
    return True, data

