class InMemoryRelationalStore:
    def __init__(self):
        self.users = {}
        self.accounts = {}

    def add_user(self, user_id: int, name: str):
        self.users[user_id] = {'id': user_id, 'name': name}

    def add_account(self, account_id: int, user_id: int, currency: str = 'RUB'):
        if user_id not in self.users:
            raise ValueError(f'User {user_id} does not exist')
        self.accounts[account_id] = {'id': account_id, 'user_id': user_id, 'currency': currency}

    def get_user_accounts(self, user_id: int) -> list[dict]:
        return [acc for acc in self.accounts.values() if acc['user_id'] == user_id]

