solutionCode:
class BankApplication:
    def __init__(self):
        self.tokens = set()
        self.accounts = {}
        self._next_id = 1

    def register_user(self, username: str, password: str) -> str:
        if len(password) < 6:
            raise ValueError('Password too short')
        token = f'token_{username}'
        self.tokens.add(token)
        return token

    def _check_token(self, token: str):
        if not token or token not in self.tokens:
            raise PermissionError('Invalid token')

    def open_account(self, token: str, currency: str = 'RUB', initial_deposit: float = 0.0) -> int:
        self._check_token(token)
        acc_id = self._next_id
        self._next_id += 1
        self.accounts[acc_id] = {'currency': currency, 'balance': float(initial_deposit)}
        return acc_id

    def get_balance(self, token: str, account_id: int) -> float:
        self._check_token(token)
        if account_id not in self.accounts:
            raise KeyError('Account not found')
        return self.accounts[account_id]['balance']

    def transfer(self, token: str, from_id: int, to_id: int, amount: float) -> dict:
        self._check_token(token)
        if amount <= 0:
            raise ValueError('Invalid amount')
        if from_id not in self.accounts or to_id not in self.accounts:
            raise KeyError('Account not found')
        if self.accounts[from_id]['balance'] < amount:
            raise ValueError('Insufficient funds')
        self.accounts[from_id]['balance'] -= amount
        self.accounts[to_id]['balance'] += amount
        return {'status': 'success', 'from_id': from_id, 'to_id': to_id, 'amount': amount}

