guide.solution:
#include <iostream>
#include <string>
#include <vector>

struct Item {
    std::string name;
    int count;
};

class Warehouse {
private:
    std::vector<Item> items;
public:
    void addItem(std::string name, int count) {
        items.push_back(Item{name, count});
    }
    int getTotalItems() {
        int total = 0;
        for (const auto& item : items) {
            total += item.count;
        }
        return total;
    }
};

int main() {
    Warehouse wh;
    wh.addItem("Книги", 15);
    wh.addItem("Тетради", 25);
    std::cout << wh.getTotalItems() << std::endl;
    return 0;
}

