using System;
using System.Collections.Generic;

class Product {
    public string Name;
    public int Price;
    public Product(string name, int price) {
        Name = name;
        Price = price;
    }
}

class Program {
    static void Main() {
        List<Product> items = new List<Product>();
        items.Add(new Product("Ноутбук", 50000));
        items.Add(new Product("Мышь", 1500));

        int total = 0;
        foreach (Product p in items) {
            total += p.Price;
        }
        Console.WriteLine($"Итого товаров: {items.Count}, сумма: {total} руб.");
    }
}

