struct Server {
    name: String,
    cores: i32,
}

fn main() {
    let servers = vec![
        Server { name: String::from("Node-A"), cores: 8 },
        Server { name: String::from("Node-B"), cores: 16 },
    ];

    let mut total_cores = 0;
    for s in servers {
        total_cores += s.cores;
    }
    println!("Всего серверов: 2, ядер: {}", total_cores);
}

