guide.solution:
function calculateDeliveredTotal(ordersJson) {
  const orders = JSON.parse(ordersJson);
  return orders
    .filter(o => o.delivered)
    .reduce((sum, o) => sum + o.amount, 0);
}

const testOrders = '[{"id":1,"amount":150,"delivered":true},{"id":2,"amount":200,"delivered":false},{"id":3,"amount":250,"delivered":true}]';
console.log(calculateDeliveredTotal(testOrders));

