guide.solution:
async function retryOperation(operationFn, maxAttempts) {
  let lastError;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await operationFn();
    } catch (err) {
      lastError = err;
      if (attempt === maxAttempts) throw lastError;
    }
  }
}

