const res = dispatchCartAction({ action: 'increase', id: 42 }, h);
[res, incId]

let remId = null;
const h = { onRemove: (id) => { remId = id; return 'rem-done'; } };
const res = dispatchCartAction({ action: 'remove', id: 99 }, h);
[res, remId]

guide.solution:
function dispatchCartAction(targetData, handlers) {
  if (!targetData || !targetData.action) return null;
  switch (targetData.action) {
    case 'increase':
      return handlers.onIncrease ? handlers.onIncrease(targetData.id) : null;
    case 'decrease':
      return handlers.onDecrease ? handlers.onDecrease(targetData.id) : null;
    case 'remove':
      return handlers.onRemove ? handlers.onRemove(targetData.id) : null;
    default:
      return null;
  }
}

