class FormStateManager {
  constructor(initialValues = {}) {
    this.values = { name: '', email: '', address: '', ...initialValues };
    this.errors = {};
    this.validateAll();
  }
  validateField(field, val) {
    const v = (val || '').trim();
    if (field === 'name') {
      if (v.length < 2) return 'Имя слишком короткое';
    } else if (field === 'email') {
      if (!v.includes('@') || !v.includes('.')) return 'Некорректный email';
    } else if (field === 'address') {
      if (v.length < 5) return 'Укажите полный адрес';
    }
    return null;
  }
  validateAll() {
    this.errors = {};
    for (const f of ['name', 'email', 'address']) {
      const err = this.validateField(f, this.values[f]);
      if (err) this.errors[f] = err;
    }
  }
  setValue(field, val) {
    this.values[field] = val;
    const err = this.validateField(field, val);
    if (err) this.errors[field] = err;
    else delete this.errors[field];
  }
  getValues() { return { ...this.values }; }
  getErrors() { return { ...this.errors }; }
  isValid() {
    return Object.keys(this.errors).length === 0 &&
      Boolean(this.values.name?.trim() && this.values.email?.trim() && this.values.address?.trim());
  }
}

