class CartManager {
  constructor() {
    this.items = [];
    this.discountRate = 0;
  }
  addItem(product, qty = 1) {
    const existing = this.items.find(x => x.id === product.id);
    if (existing) {
      existing.quantity += qty;
    } else {
      this.items.push({ ...product, quantity: qty });
    }
  }
  updateQuantity(id, qty) {
    if (qty <= 0) {
      this.removeItem(id);
    } else {
      const it = this.items.find(x => x.id === id);
      if (it) it.quantity = qty;
    }
  }
  removeItem(id) {
    this.items = this.items.filter(x => x.id !== id);
  }
  applyPromo(code) {
    if (code === 'DEVFORGE10') this.discountRate = 0.10;
  }
  getSummary() {
    const subtotal = this.items.reduce((sum, it) => sum + it.price * it.quantity, 0);
    const discount = Math.round(subtotal * this.discountRate);
    return {
      items: this.items.map(it => ({ ...it })),
      subtotal,
      discount,
      total: subtotal - discount
    };
  }
}

