class StoreApplication {
  constructor(initialProducts = []) {
    this.products = [...initialProducts];
    this.cart = [];
    this.nextOrderId = 1001;
  }
  queryCatalog({ search = '', category = 'all', sort = 'none', page = 1, pageSize = 5 } = {}) {
    let res = this.products.filter(p => {
      const matchSearch = !search || p.name.toLowerCase().includes(search.toLowerCase());
      const matchCat = category === 'all' || p.category === category;
      return matchSearch && matchCat;
    });
    if (sort === 'asc') res.sort((a, b) => a.price - b.price);
    else if (sort === 'desc') res.sort((a, b) => b.price - a.price);
    const totalCount = res.length;
    const totalPages = Math.ceil(totalCount / pageSize) || 1;
    const start = (page - 1) * pageSize;
    const items = res.slice(start, start + pageSize);
    return { items, totalCount, totalPages, currentPage: page };
  }
  addToCart(productId, qty = 1) {
    const prod = this.products.find(p => p.id === productId);
    if (!prod || !prod.inStock) return false;
    const existing = this.cart.find(it => it.id === productId);
    if (existing) existing.quantity += qty;
    else this.cart.push({ ...prod, quantity: qty });
    return true;
  }
  getCartSummary() {
    const totalQty = this.cart.reduce((sum, it) => sum + it.quantity, 0);
    const totalCost = this.cart.reduce((sum, it) => sum + it.price * it.quantity, 0);
    return { items: [...this.cart], totalQty, totalCost };
  }
  submitOrder(customer) {
    if (this.cart.length === 0) throw new Error('Cart is empty');
    if (!customer || !customer.name || customer.name.trim().length < 2) throw new Error('Validation failed');
    if (!customer.email || !customer.email.includes('@') || !customer.email.includes('.')) throw new Error('Validation failed');
    if (!customer.address || customer.address.trim().length < 5) throw new Error('Validation failed');
    const total = this.getCartSummary().totalCost;
    const orderId = this.nextOrderId++;
    this.cart = [];
    return { orderId, status: 'confirmed', total, customer };
  }
}

