guide.solution:
class AsyncDataLoader {
  constructor(fetcherFn) {
    this.fetcherFn = fetcherFn;
    this.state = { status: 'idle', data: null, error: null };
  }
  async load(param) {
    this.state = { status: 'loading', data: null, error: null };
    try {
      const result = await this.fetcherFn(param);
      this.state = { status: 'success', data: result, error: null };
      return result;
    } catch (err) {
      const msg = err.message || String(err);
      this.state = { status: 'error', data: null, error: msg };
      throw err;
    }
  }
  getState() {
    return { ...this.state };
  }
}

