guide.solution:
class InMemoryRepo<T extends { id: number }> {
  private items: T[] = [];
  public add(item: T): void {
    this.items.push(item);
  }
  public getById(id: number): T | undefined {
    return this.items.find(x => x.id === id);
  }
  public count(): number {
    return this.items.length;
  }
}

const repo = new InMemoryRepo<{ id: number; title: string }>();
repo.add({ id: 1, title: 'Урок 1' });
repo.add({ id: 2, title: 'Урок 2' });
const item = repo.getById(2);
console.log(`${repo.count()} ${item ? item.title : ''}`);

