local Player = {}
Player.__index = Player

function Player.new(name, location)
    local self = setmetatable({}, Player)
    self.name = name
    self.location = location
    self.inventory = {}
    return self
end

function Player:add_item(item)
    table.insert(self.inventory, item)
end

function Player:move_to(new_loc)
    self.location = new_loc
end

function Player:status()
    return string.format("%s находится в: %s | Инвентарь: %s", self.name, self.location, table.concat(self.inventory, ", "))
end

local hero = Player.new("Рыцарь", "Деревня")
hero:add_item("Меч")
hero:move_to("Пещера")
hero:add_item("Щит")
